//! FORM action uses actual document URL and live base without navigation.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post><input id=area name=q value=Seed></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-action.test/source?old=1#frag",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn form_action_canonical_url_fallback_and_usv_once(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'action');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get action'||a.set.name!=='set action'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'action')||x.action!=='https://form-action.test/source?old=1#frag')throw 'canonical';x.action='';if(x.action!=='https://form-action.test/source?old=1#frag')throw 'empty fallback';var calls=0;x.action={toString:function(){calls++;return '../send?x=1#ok';},valueOf:function(){throw 'hint';}};if(calls!==1||x.action!=='https://form-action.test/send?x=1#ok'||x.getAttributeNS(null,'action')!=='../send?x=1#ok')throw 'relative';x.action='https://[';if(x.action!=='https://[')throw 'invalid fallback';x.action='A\ud800Z';if(x.getAttributeNS(null,'action')!=='A\ufffdZ'||x.action!=='https://form-action.test/A%EF%BF%BDZ')throw 'USV setter';x.setAttribute('action','https://[\ud800');if(x.action!=='https://[\ufffd'||x.getAttributeNS(null,'action')!=='https://[\ud800')throw 'scalar getter raw attribute';"#);}
#[test]
fn form_action_base_changes_leave_empty_at_document_url(){let(mut d,mut f,mut p)=fixture();let base=crate::navigation::address("https://other-action.test/base/",&crate::navigation::Location::home()).unwrap();p.set_resource_base(&base);run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');if(x.action!=='https://form-action.test/source?old=1#frag')throw 'missing ignores base';x.action='';if(x.action!=='https://form-action.test/source?old=1#frag')throw 'empty ignores base';x.action='submit';if(x.action!=='https://other-action.test/base/submit')throw 'live base';");}
#[test]
fn form_action_inert_namespace_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','form');x.setAttributeNS('urn:foreign','action','https://foreign.test/');x.setAttributeNS(null,'ACTION','https://upper.test/');if(x.action!=='about:blank')throw 'inert namespace';x.action='https://inert-action.test/one';var y=x.cloneNode(false);y.action='https://inert-action.test/two';if(x.action!=='https://inert-action.test/one'||y.action!=='https://inert-action.test/two')throw 'independent';x.action='';if(x.action!=='about:blank')throw 'inert empty';");}

#[test]
fn form_action_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'action'),calls=0;if(a.get.call(x)!=='https://form-action.test/source?old=1#frag')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-form-action.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'https://form-action.test/get';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://form-action.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'https://form-action.test/get');if(x.action!=='https://form-action.test/get')throw 'fresh recovery';");}

#[test]
fn form_action_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.action='https://form-action.test/post';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.form_action_get(object).map(|_|())}else{bridge.form_action_set(object,&Value::String("https://form-action.test/longer-growing-value-than-the-existing-content-attribute".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.action='https://form-action.test/get';if(x.action!=='https://form-action.test/get'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn form_action_authority_named_control_and_abrupt_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),n=document.getElementById('area'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'action'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'brand missing';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';n.setAttribute('name','action');if(x.action!==n)throw 'named precedence';a.set.call(x,{toString:function(){calls++;x.setAttribute('data-side','kept');return 'send';}});if(calls!==1||x.action!==n||a.get.call(x)!=='https://form-action.test/send')throw 'saved named authority';var marker={};try{a.set.call(x,{toString:function(){throw marker;}});throw 'abrupt missing';}catch(e){if(e!==marker)throw e;}if(a.get.call(x)!=='https://form-action.test/send')throw 'abrupt atomicity';n.setAttribute('name','q');Object.defineProperty(P,'action',{get:function(){return 'author';},configurable:true});a.set.call(x,'next');if(x.action!=='author'||a.get.call(x)!=='https://form-action.test/next')throw 'saved prototype authority';Object.defineProperty(P,'action',a);");}
#[test]
fn form_action_attribute_writers_observer_identity_and_native_submission(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),editor=document.getElementById('area');editor.value='Edited';x.action='before';var attribute=x.getAttributeNodeNS(null,'action'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for code in ["x.setAttribute('action','send');","x.setAttributeNS(null,'action','send');","attribute.value='send';","attribute.nodeValue='send';","attribute.textContent='send';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.action='before';watch.takeRecords();");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.action!=='https://form-action.test/send'||x.getAttributeNodeNS(null,'action')!==attribute||records.length!==1||records[0].oldValue!=='before'||records[0].attributeName!=='action'||editor.value!=='Edited')throw 'attribute mutation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let l=crate::navigation::address("https://form-action.test/source",&crate::navigation::Location::home()).unwrap();let result=f.submit_request(&d,owner,None,&l,&l).unwrap();assert_eq!(result.location.display(),"https://form-action.test/send");let crate::http::Request::FormPost{body,..}=result.request else{panic!("POST")};assert_eq!(body,b"q=Edited");}

#[test]
fn form_action_null_undefined_unsupported_url_and_fresh_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.action=null;if(x.getAttributeNS(null,'action')!=='null'||x.action!=='https://form-action.test/null')throw 'null';x.action=undefined;if(x.getAttributeNS(null,'action')!=='undefined'||x.action!=='https://form-action.test/undefined')throw 'undefined';x.action='mailto:user@example.test';");let before=format!("{:?}",d.nodes);let error=p.runtime.execute("x.action;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("HTTP(S)"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);p.begin_job();run(&mut d,&mut f,&mut p,"x.action='https://FORM-ACTION.test:443/recovered';if(x.action!=='https://form-action.test/recovered')throw 'recovery';");}
#[test]
fn form_action_local_lexical_reflection_does_not_open_missing_target(){struct File(std::path::PathBuf);impl Drop for File{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}let file=File(std::env::temp_dir().join(format!("chezcat-form-action-{}.html",std::process::id())));std::fs::write(&file.0,"<!doctype html>").unwrap();let missing=file.0.with_file_name(format!("chezcat-form-action-missing-{}.html",std::process::id()));assert!(!missing.exists());let local=crate::navigation::address(file.0.to_str().unwrap(),&crate::navigation::Location::home()).unwrap();let(mut d,mut f,mut p)=fixture();p.set_location(&local);p.set_resource_base(&local);let raw=missing.file_name().unwrap().to_str().unwrap();let expected=crate::navigation::selection_url(raw,&local).unwrap();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('form');x.action='{raw}';"));let value=p.runtime.execute("x.action;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();assert!(matches!(value,Value::String(ref s)if s==&expected));assert!(!missing.exists());assert_eq!(p.error_count(),0);}
